theorem sprung_lambda_invariant_difference_formula
  (E : EllipticCurve ℚ) (hE_ss : SupersingularReduction E 2) (hE_sf : Squarefree (conductor E))
  (D : ℤ) (hD_sf : Squarefree D) (hD_pos : 0 < D) (hD_mod : D % 4 = 1)
  (star : SharpFlat) (i : Fin 2) (h_mu_zero : mu_invariant E star i = 0) :
  lambda_invariant (quadratic_twist E D) star i = lambda_invariant E star i +
    (prime_divisors D).sum fun ell =>
      if (ell : ℤ) ∣ conductor E then 2^(padicVal 2 ((ell^2 - 1) / 8))
      else if 2 ∣ (E.reduce ell).card then 2^(padicVal 2 ((ell^2 - 1) / 8) + 1)
      else 0 :=
by sorry
